-- ============================================================================
-- UNIPULSE — SEED DATA
-- Run this AFTER schema.sql. Countries are already seeded inside schema.sql.
-- This file adds all 147 seed universities from the brief.
--
-- IMPORTANT — data honesty:
-- Every university below is inserted with data_confidence = 'unavailable' and
-- priority_tier = 3 ("smaller but viable, needs market testing"). No student
-- counts, international %, or postgrad numbers are guessed — the brief is
-- explicit that these must come from HESA / IRCC-StatCan / Australian Dept of
-- Education / IIE Open Doors-IPEDS, or be left blank. Fill those fields in
-- from the admin dashboard (or directly in Supabase) as you gather real data,
-- and the opportunity_score recalculates automatically.
--
-- The one exception: priority_tier is bumped to 1 below for a short list of
-- globally well-known research-intensive universities. That's an editorial
-- starting point for where to focus first outreach, not a data claim —
-- re-tier freely once real numbers come in.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Editorial tier-1 starting list (well-known, large, internationally-recruiting
-- research universities — re-tier as real data arrives)
-- ----------------------------------------------------------------------------
update universities set priority_tier = 1 where slug in (
  'imperial-college-london','london-school-of-economics-and-political-science','university-college-london',
  'university-of-warwick','university-of-manchester','university-of-edinburgh','university-of-oxford',
  'university-of-cambridge','king-s-college-london',
  'university-of-toronto','ubc','mcgill','university-of-waterloo',
  'university-of-melbourne','monash-university','university-of-sydney','unsw-sydney','australian-national-university',
  'new-york-university','columbia-university','university-of-southern-california','university-of-michigan',
  'uc-berkeley','ucla','university-of-washington','carnegie-mellon-university','georgia-institute-of-technology'
);
